import {adventureRecords} from './adventure-curriculum';
/** Original Aarambh teaching notes. Topic links are alignment references, not copied lessons or educator approval. */
export type TeachingRecord={id:string;grade:number;title:string;strand:string;prerequisites:string[];explanation:string;goal:string;example:{question:string;steps:string[];answer:string};objects:string;story:string;watchFor:string;response:string;transfer:string};
const r=(id:string,grade:number,title:string,strand:string,prerequisites:string[],explanation:string,goal:string,question:string,steps:string[],answer:string,objects:string,story:string,watchFor:string,response:string,transfer:string):TeachingRecord=>({id,grade,title,strand,prerequisites,explanation,goal,example:{question,steps,answer},objects,story,watchFor,response,transfer});
export const teachingRecords:TeachingRecord[]=[
...adventureRecords,
// Class 1: quantities before notation.
r('count',1,'Counting with meaning','Number sense',[], 'Count each object exactly once. The last number spoken tells how many objects are in the whole group, even when they are rearranged.','Match one number word to one object and state the total.','There are 6 buttons. How many are there after spreading them out?',['Touch each button once.','Say 1, 2, 3, 4, 5, 6.','Spreading the buttons does not add or remove any.'],'6','Move each counted object into a second tray.','Count cups needed for six guests.','Counting an object twice, or changing the total when spacing changes.','Move counted items aside and compare the same group before and after rearranging.','Count sounds or claps instead of visible objects.'),
r('compare',1,'More, fewer and equal','Number sense',['count'],'Two groups can be compared by matching their objects one to one. The group with unmatched objects has more; equal groups have none left unmatched.','Compare small quantities without relying on the space they occupy.','Which is more: 7 pebbles or 5 pebbles?',['Match one pebble from each group.','Five pairs can be made.','Two pebbles remain in the group of seven.'],'7 pebbles','Make paired rows of counters, then spread the shorter row wider.','Check whether there is a plate for every person.','Choosing the more spread-out group as the larger quantity.','Pair the objects to separate number from arrangement.','Compare two groups drawn with different-sized dots.'),
r('add',1,'Putting things together','Operations',['count'],'Addition combines quantities. Counting on starts from one quantity and adds one count for each object in the other group.','Connect combining objects with an addition statement.','What is 4 + 3?',['Keep four counters together.','Add three counters, counting 5, 6, 7.','The combined group contains seven.'],'7','Join two groups of counters and record the total.','Four birds sit on a wall; three more arrive.','Restarting or skipping a count when groups are combined.','Touch or move each new counter while counting on.','Show the same addition as a missing-total number sentence.'),
r('subtract',1,'Taking a few away','Operations',['count','add'],'Subtraction can describe taking away or finding a difference. When taking away, the remaining quantity is the starting amount minus the amount removed.','Connect removing objects with subtraction.','There are 9 leaves. Take away 4. How many remain?',['Start with nine leaves.','Move four leaves to another place.','Count the five remaining leaves.'],'5','Move removed counters out of the counted group.','Nine passengers are on a bus; four get off.','Reporting the number removed instead of the number left.','Keep the removed and remaining groups separate and ask what the question names.','Find the missing part in 4 + ? = 9.'),
r('zero',1,'Zero means none','Number sense',['count','subtract'],'Zero describes a quantity with no objects. Adding zero does not change a quantity, and removing all of a group leaves zero.','Use zero to describe an empty collection.','Five blocks are in a box. All five are taken out. How many remain?',['Begin with five blocks.','Take every block out.','The box is empty, so its quantity is zero.'],'0','Compare an empty tray with trays holding one and two objects.','Count the apples left after the last apple is used.','Treating zero as a missing answer rather than a number.','Label an empty group with the numeral 0 and say what it represents.','Explain why 6 + 0 remains 6.'),
r('shapes1',1,'Recognising flat shapes','Geometry',['count'],'A triangle has three straight sides; a rectangle has four straight sides and four right angles. Turning a shape does not change its defining properties.','Recognise shapes through their sides, including rotated examples.','How many straight sides does a triangle have?',['Trace the outline.','Count each straight edge once.','There are three edges.'],'3','Trace cut-out shapes and turn them in different directions.','Find triangle and rectangle outlines in classroom objects.','Recognising a triangle only when one corner points upwards.','Rotate the same cut-out and trace its unchanged sides.','Draw a triangle that points sideways.'),
r('pattern1',1,'Repeating patterns','Patterns',['compare'],'A repeating pattern is made by using the same unit again and again. Identify the whole unit before predicting what comes next.','Find and repeat a short pattern unit.','The pattern is clap, tap, clap, tap. What action comes next?',['The repeating unit is clap, tap.','Two complete units have been made.','Begin the next unit with clap.'],'Clap','Arrange alternating coloured objects in a row.','Create a repeating clap-and-tap rhythm.','Continuing by appearance without identifying a repeating unit.','Enclose one full repeat and copy that group.','Continue an A, B, B pattern using movements.'),
r('length1',1,'Comparing lengths','Measurement',['compare'],'To compare lengths directly, put the objects beside one another with one end aligned. A different starting position can make a shorter object look longer.','Compare lengths from a common starting point.','One strip is 4 blocks long and another is 6 of the same blocks long. Which is longer?',['Use identical blocks for both strips.','Align their starting ends.','Six equal blocks cover more length than four.'],'The 6-block strip','Line up ribbons at one end before comparing.','Choose a strip long enough to wrap around a small box.','Comparing objects that start at different positions.','Place both starting ends on the same marked line.','Order three differently placed strips by length.'),
// Class 2.
r('place',2,'Tens and ones','Number sense',['count','add'],'Ten ones can be exchanged for one ten without changing the quantity. In a two-digit number, the first digit counts tens and the second counts remaining ones.','Build and partition two-digit numbers.','What does 43 represent?',['Make four bundles of ten.','Keep three single objects.','40 + 3 equals 43.'],'4 tens and 3 ones','Bundle straws in tens and leave single straws loose.','Pack 43 pencils into boxes of ten.','Reading a digit without considering its position.','Build both 43 and 34 and compare the quantities.','Represent 43 as 3 tens and 13 ones.'),
r('tens',2,'Adding bigger numbers','Operations',['place','add'],'Two-digit addition combines tens with tens and ones with ones. A total of ten or more ones can be exchanged for another ten.','Add two-digit quantities while explaining place value.','What is 26 + 17?',['Combine 2 tens and 1 ten to make 3 tens.','6 ones + 7 ones = 13 ones.','Exchange 10 ones for 1 ten: 4 tens and 3 ones.'],'43','Use bundles and loose counters, making the exchange visible.','Combine two collections of 26 and 17 stamps.','Writing 313 after adding tens and ones separately.','Show that 13 ones are 1 ten and 3 ones.','Solve the same addition with a number line.'),
r('regroup2',2,'Subtracting with an exchange','Operations',['place','subtract'],'When there are too few ones to subtract, exchange one ten for ten ones. The value is unchanged: 42 can be represented as 3 tens and 12 ones.','Explain a place-value exchange during subtraction.','What is 42 − 17?',['Exchange 1 of the 4 tens: 3 tens and 12 ones.','12 ones − 7 ones = 5 ones.','3 tens − 1 ten = 2 tens.'],'25','Physically untie one bundle of ten straws.','Spend ₹17 from ₹42 using pretend tens and ones.','Subtracting the smaller digit from the larger digit in each column.','Build the starting amount and remove the stated quantity.','Check the result using 25 + 17.'),
r('skip2',2,'Counting in equal steps','Patterns',['add','count'],'Skip-counting adds the same quantity at every step. Counting in fives can represent the total in successive groups of five.','Continue an equal-step sequence and explain the step.','Continue 5, 10, 15, 20, __.',['Find the change between neighbouring terms.','Each step adds five.','20 + 5 = 25.'],'25','Jump across a floor number line in equal steps.','Count fingers on one hand, two hands, then three hands.','Changing the step after crossing a multiple of ten.','Mark each equal jump explicitly before continuing.','Start at 3 and count on in steps of five.'),
r('money2',2,'Making an amount of money','Measurement',['tens','subtract'],'An amount can be made using different combinations of coins or notes. Their values, not the number of pieces, determine the total.','Combine denominations and find simple change.','You pay ₹20 for an item costing ₹13. What change is due?',['Count up from ₹13 to ₹20.','13 + 7 = 20.','The difference is seven rupees.'],'₹7','Use clearly labelled pretend coins of different values.','Buy one item from a pretend classroom shop.','Assuming more coins always means more money.','Compare five ₹1 coins with one ₹10 coin.','Make ₹12 using two different combinations.'),
r('time2',2,'Hours and daily events','Measurement',['count','skip2'],'A clock measures time passing. The minute hand completes one turn in an hour; there are 60 minutes in an hour.','Connect whole-hour times with durations.','An activity starts at 2 o’clock and ends at 4 o’clock. How many hours pass?',['Count the interval from 2 to 3.','Count the interval from 3 to 4.','Two one-hour intervals pass.'],'2 hours','Move the hands on a teaching clock through whole hours.','Plan the time between lunch and an afternoon game.','Counting both clock labels rather than the intervals.','Mark the jumps between times instead of counting endpoints.','Find the end time of a two-hour activity starting at 5.'),
r('measure2',2,'Measuring without gaps','Measurement',['length1','count'],'Repeated units must be equal in size and placed end to end. Gaps or overlaps change the count without correctly measuring the object.','Measure length using equal repeated units.','A pencil covers 8 equal centimetre intervals on a ruler. How long is it?',['Align the pencil with the zero mark.','Count the intervals, not just the printed marks.','Eight one-centimetre intervals give eight centimetres.'],'8 cm','Measure with identical blocks before using a ruler.','Measure a strip for a bookmark.','Starting at the ruler’s edge when zero is elsewhere.','Find the zero mark and align the object with it.','Measure an object that starts at the 2 cm mark and ends at 9 cm.'),
r('data2',2,'Sorting and counting data','Data & chance',['count','compare'],'Data can be organised into named categories. Count each item once in the category chosen by the sorting rule.','Create and read a simple count table.','A table shows 4 red buttons and 6 blue buttons. How many buttons are there?',['Identify the two categories.','Add their counts: 4 + 6.','The total is ten buttons.'],'10','Sort buttons by one chosen property and label each group.','Record favourite fruits using one vote per person.','Counting one item in more than one category unintentionally.','State the sorting rule and check each item against it.','Show the same counts as rows of picture symbols.'),
// Class 3.
r('hundreds3',3,'Hundreds, tens and ones','Number sense',['place'],'A hundred contains ten tens or one hundred ones. A zero digit can hold a place when that position has no units.','Represent and compare three-digit numbers.','What is 305 made of?',['The 3 is in the hundreds place: 300.','The tens digit is zero.','The ones digit is 5, so 300 + 0 + 5 = 305.'],'3 hundreds, 0 tens, 5 ones','Build numbers using hundred squares, ten rods and ones.','Pack 305 cards into hundreds, tens and singles.','Writing 305 as 35 because there are no tens.','Keep labelled place-value columns, including the empty one.','Explain how 350 differs from 305.'),
r('multiply',3,'Equal groups','Operations',['add','skip2'],'Multiplication describes a number of equal-sized groups. An array shows rows and columns and connects repeated addition to a product.','Interpret a product as equal groups.','What is 4 × 3?',['Make four groups with three objects each.','Add 3 + 3 + 3 + 3.','The total is twelve.'],'12','Arrange counters in four rows of three.','Put three cups on each of four trays.','Adding the number of groups to the group size.','Build both quantities: groups first, then items in each group.','Turn the array to show 3 × 4 has the same total.'),
r('divide',3,'Sharing fairly','Operations',['multiply','subtract'],'Division can find a group size or the number of groups. Sharing equally requires every group to receive the same amount.','Relate equal sharing to multiplication.','Share 18 counters equally among 3 groups. How many per group?',['Deal one counter to each group in turn.','Continue until all 18 have been shared.','Each group has 6; 3 × 6 = 18.'],'6','Share counters into three bowls.','Distribute 18 pencils equally among three tables.','Giving each group a different number of objects.','Deal one at a time and compare the group sizes.','Instead make groups of 3 and count how many groups result.'),
r('remainders3',3,'When some are left over','Operations',['divide'],'A remainder is the amount left after making complete equal groups. It must be smaller than the divisor; otherwise another group can be made.','Explain a quotient and a remainder in context.','Put 17 pencils into packs of 5. How many pencils are left?',['Three full packs use 3 × 5 = 15 pencils.','17 − 15 = 2.','Two is smaller than five, so no further full pack is possible.'],'2 pencils','Make equal groups and keep the leftover objects visible.','Pack pencils into boxes that each hold five.','Accepting a remainder as large as the group size.','Ask whether another complete group can be formed.','Explain why 17 passengers need four 5-seat vehicles.'),
r('fractions3',3,'Equal parts of one whole','Fractions',['divide','shapes1'],'A fraction names equal parts of a specified whole. The denominator tells how many equal parts form that whole; the numerator tells how many are selected.','Describe halves and quarters using equal parts.','A rectangle has 4 equal parts. One is shaded. What fraction is shaded?',['Check that all four parts have equal area.','One part is selected out of four.','Write one quarter as 1/4.'],'1/4','Fold paper into equal parts and compare the pieces.','Share a sandwich equally among four people.','Calling any four pieces quarters even when their sizes differ.','Compare the areas of the pieces and rebuild equal parts.','Show one quarter using a collection of twelve counters.'),
r('clock3',3,'Minutes and elapsed time','Measurement',['time2','skip2'],'One hour equals 60 minutes. For elapsed time, count the minutes between the start and end, crossing the hour in manageable steps.','Find simple durations across an hour.','How many minutes pass from 2:45 to 3:10?',['2:45 to 3:00 is 15 minutes.','3:00 to 3:10 is 10 minutes.','15 + 10 = 25.'],'25 minutes','Move a clock hand to the hour, then to the final time.','Time a reading session that crosses the hour.','Treating clock minutes as if an hour had 100.','Use 60-minute clock intervals and count through the hour.','Find the finishing time of a 25-minute activity starting at 2:45.'),
r('length3',3,'Centimetres and metres','Measurement',['measure2','hundreds3'],'A metre is the same length as 100 centimetres. Converting a length changes its numerical description, not the physical length.','Use the relation between metres and centimetres.','How many centimetres are in 2 m 35 cm?',['Two metres equals 200 centimetres.','Add the extra 35 centimetres.','200 + 35 = 235.'],'235 cm','Build a metre strip and mark its centimetres.','Measure fabric for a banner.','Reading 2 m 35 cm as 235 metres or 2.35 centimetres.','Label the unit at each conversion step.','Express 180 cm using metres and centimetres.'),
r('shapes3',3,'Corners, sides and properties','Geometry',['shapes1','compare'],'Shapes can be described using properties such as sides, vertices and equal lengths. A square is also a rectangle because it has four right angles.','Describe a shape through properties rather than orientation.','A square has four equal sides. If one side is 3 cm, what is the total length of its sides?',['All four sides are 3 cm.','Add 3 + 3 + 3 + 3.','The boundary length is 12 cm.'],'12 cm','Build closed shapes with sticks and compare their corners.','Describe a tile so someone else can identify its shape.','Thinking a rotated square has become a different shape.','Rotate one cut-out while checking the same properties.','Find a rectangle that is not a square and explain why.'),
// Class 4.
r('multiply4',4,'Multiplying by partitioning','Operations',['multiply','hundreds3'],'The distributive property lets a number be split into useful parts. Multiplying 23 by 4 is the same as multiplying 20 and 3 by 4, then adding.','Explain a two-digit product through place value.','What is 23 × 4?',['Split 23 into 20 + 3.','20 × 4 = 80 and 3 × 4 = 12.','80 + 12 = 92.'],'92','Split a 23-by-4 array into 20-by-4 and 3-by-4 pieces.','Count four boxes each containing 23 pencils.','Multiplying only the ones digit.','Label every partition and account for each partial product.','Use 25 × 4 minus 2 × 4 to find the same result.'),
r('divide4',4,'Dividing by partitioning','Operations',['divide','multiply4'],'A dividend can be split into convenient multiples of the divisor. Combining the partial quotients preserves the equal group size.','Explain division with known multiplication facts.','What is 84 ÷ 4?',['Split 84 into 80 + 4.','80 ÷ 4 = 20 and 4 ÷ 4 = 1.','20 + 1 = 21.'],'21','Share eight tens and four ones across four groups.','Share 84 cards among four teams.','Dividing each digit without considering its place value.','Represent the tens and ones before partitioning.','Check the quotient by multiplying it by four.'),
r('fraction',4,'Equivalent fractions','Fractions',['fractions3','multiply'],'Equivalent fractions name the same quantity relative to the same whole. Multiplying numerator and denominator by the same positive integer subdivides the parts without changing the amount.','Explain why two fractions are equivalent.','Complete 1/2 = ?/8.',['The whole is divided into eight rather than two equal parts.','Each half contains four of these smaller parts.','Multiply numerator and denominator by 4.'],'4/8','Fold equal paper strips into halves and eighths.','Compare half a chocolate bar with four eighths of an identical bar.','Adding the same number to numerator and denominator.','Shade both proposed fractions on identical wholes and compare.','Explain why 2/3 equals 6/9.'),
r('perimeter',4,'Around the edge','Measurement',['add','shapes3'],'Perimeter is the total length of the outside boundary. A rectangle has two equal lengths and two equal widths, so its perimeter is 2 × (length + width).','Calculate and explain rectangular perimeter.','Find the perimeter of a 6 cm by 4 cm rectangle.',['List the four sides: 6, 4, 6, 4.','Add all four lengths.','6 + 4 + 6 + 4 = 20.'],'20 cm','Trace a boundary with string and measure the string.','Find the fencing needed around a rectangular garden.','Using length × width when boundary length is requested.','Distinguish covering the inside from tracing the outside.','Draw two rectangles with the same perimeter and different shapes.'),
r('factors4',4,'Factors and multiples','Number sense',['multiply','divide'] ,'A factor divides a whole number exactly. Multiples are obtained by multiplying a number by whole numbers; these two ideas describe different relationships.','List factor pairs systematically.','What are the positive factor pairs of 12?',['1 × 12 = 12.','2 × 6 = 12.','3 × 4 = 12; the remaining pairs repeat in reverse.'],'(1,12), (2,6), (3,4)','Make all possible rectangular arrays with twelve counters.','Find rectangular arrangements of twelve chairs.','Listing multiples when factors are requested.','Ask whether the proposed number divides twelve with no remainder.','Explain why five is not a factor of twelve.'),
r('symmetry4',4,'Mirror symmetry','Geometry',['shapes3'],'A line of symmetry divides a figure into two parts that coincide when folded along the line. Equal area alone does not guarantee mirror symmetry.','Test whether a fold line produces matching halves.','How many lines of symmetry does a square have?',['Fold through the midpoints of opposite sides in both directions.','Fold along each diagonal.','All four folds make matching halves.'],'4','Fold a paper square and check exact overlap.','Design a symmetrical paper decoration.','Treating every line through the centre as a symmetry line.','Test a slanted non-diagonal fold and compare the unmatched edges.','Compare a square with a non-square rectangle.'),
r('measurement4',4,'Litres and millilitres','Measurement',['hundreds3','multiply4'],'A litre equals 1,000 millilitres. Measurements must be expressed in compatible units before adding or comparing them.','Convert and combine capacities.','What is 2 L 250 mL in millilitres?',['Two litres equals 2,000 millilitres.','Add the remaining 250 millilitres.','2,000 + 250 = 2,250.'],'2,250 mL','Fill a litre container with four equal 250 mL measures.','Work out the juice needed for several bottles.','Adding litre and millilitre numbers without converting.','Write every amount in the same unit first.','Express 1,500 mL using litres and millilitres.'),
r('data4',4,'Reading a pictograph key','Data & chance',['data2','multiply'],'A pictograph uses a key to show how much each symbol represents. Count the symbols, then use the key; one symbol need not mean one item.','Interpret a pictograph with a non-unit key.','A chart shows 4 stars, and each star means 3 books. How many books?',['Read the key: one star stands for three books.','There are four stars.','4 × 3 = 12.'],'12 books','Replace each chart symbol with the number of counters named in the key.','Represent the books read by a class in a picture chart.','Counting symbols as if every symbol meant one.','Read and explain the key before interpreting the row.','Represent the same twelve books using a key of two books per symbol.'),
// Class 5.
r('decimal_place5',5,'Tenths and hundredths','Fractions',['place','fraction'],'A tenth is one of ten equal parts of a whole; a hundredth is one of a hundred. Place value continues to the right of the decimal point.','Interpret and compare decimal quantities.','What is the value of 7 in 2.37?',['The first place after the decimal point is tenths.','The second is hundredths.','The 7 represents seven hundredths.'],'0.07','Shade hundred grids and connect each region to a decimal.','Read a length of 2.37 metres.','Treating 0.37 as larger than 0.8 because 37 is larger than 8.','Compare 37 hundredths with 80 hundredths on equal grids.','Explain why 0.50 and 0.5 have equal value.'),
r('decimal',5,'Adding decimal quantities','Fractions',['decimal_place5','tens'],'Decimal addition combines units of the same size: ones with ones, tenths with tenths and hundredths with hundredths. Aligning decimal points aligns these units.','Add decimals and explain the place-value alignment.','What is 0.7 + 0.6?',['Seven tenths plus six tenths equals thirteen tenths.','Ten tenths make one whole.','Thirteen tenths equals 1.3.'],'1.3','Combine shaded tenths and exchange ten for a whole.','Join ribbons measuring 0.7 m and 0.6 m.','Writing 0.13 by joining or misplacing digits.','Name the unit being counted: thirteen tenths, not hundredths.','Find a missing addend in 0.7 + ? = 1.3.'),
r('area',5,'Covering a surface','Measurement',['multiply','perimeter'],'Area measures how much surface is covered, using square units. A rectangle can be covered by equal rows of unit squares, so area is length × width.','Distinguish area from perimeter and use square units.','Find the area of a 5 cm by 3 cm rectangle.',['There are three rows of five unit squares.','3 × 5 = 15 squares.','Each unit square covers one square centimetre.'],'15 cm²','Cover a rectangle with unit tiles without gaps or overlaps.','Find the number of tiles needed to cover a small floor.','Reporting area in centimetres rather than square centimetres.','Separate a one-centimetre edge from a one-square-centimetre tile.','Create two different rectangles with area 12 square units.'),
r('fraction_add5',5,'Adding equal-sized parts','Fractions',['fractions3','fraction','add'],'Fractions with the same denominator use equally sized parts of the same whole. Add the counts of parts while keeping their size unchanged.','Add fractions with a common denominator.','What is 2/7 + 3/7?',['Both fractions count sevenths.','Two sevenths plus three sevenths is five sevenths.','The whole is still divided into seven equal parts.'],'5/7','Join shaded sections on identical fraction strips.','Combine portions measured in sevenths of the same length.','Adding denominators and obtaining 5/14.','Keep the original whole visible and count unchanged part sizes.','Find the missing fraction in 2/7 + ? = 6/7.'),
r('volume5',5,'Building with unit cubes','Measurement',['multiply','area'],'Volume measures occupied three-dimensional space. A cuboid made from unit cubes has length × width cubes in each layer and a given number of layers.','Count a cuboid’s volume in cubic units.','A cuboid is 4 cubes long, 3 wide and 2 high. How many cubes?',['One layer holds 4 × 3 = 12 cubes.','There are two equal layers.','12 × 2 = 24 cubes.'],'24 cubic units','Build layers of interlocking cubes, including hidden cubes.','Count small boxes packed in a rectangular crate.','Counting only the cubes visible on the front.','Disassemble the model into complete layers.','Find a different cuboid made from twenty-four unit cubes.'),
r('angles5',5,'Angles measure turns','Geometry',['shapes3','symmetry4'],'An angle measures the turn between two rays sharing an endpoint. Longer arms do not make a larger angle; the opening determines its size.','Compare acute, right and obtuse angles.','A quarter turn is how many degrees?',['A full turn is 360°.','A quarter is one of four equal parts.','360 ÷ 4 = 90.'],'90°','Open two strips joined at one end and compare turns.','Describe how far a door turns when opened.','Judging angle size from the lengths of its arms.','Draw the same opening with long and short arms.','Show a half turn as two right angles.'),
r('patterns5',5,'Rules behind number patterns','Patterns',['skip2','multiply4'],'A sequence is ordered. An explicit rule describes a term using its position; a step rule tells how to get from one term to the next.','Describe an equal-step pattern and locate a later term.','Find the fifth term of 4, 7, 10, 13, …',['Each step adds three.','The fourth term is thirteen.','Add three once more to get sixteen.'],'16','Build growing patterns of counters and label their positions.','Add three tiles to a design at each stage.','Confusing a term’s position with its value.','Make a two-row table for position and value.','Describe the change when the same pattern starts at seven.'),
r('data5',5,'Reading tables and differences','Data & chance',['data4','subtract'],'A table organises quantities with labels and units. To compare entries, identify the relevant rows or columns before performing an operation.','Choose the correct entries and compare them.','A table records 28 visitors on Monday and 35 on Tuesday. How many more on Tuesday?',['Use the two stated daily counts.','Find the difference: 35 − 28.','Seven more visitors came on Tuesday.'],'7 visitors','Make a labelled two-column table with counters for each count.','Compare daily attendance at a club.','Adding entries when the question asks how many more.','Restate the question as finding the gap between two counts.','Ask a total question using the same table and explain the different operation.'),
// Class 6: proposed foundation sequence, edition alignment still requires review.
r('integer',6,'On either side of zero','Number sense',['subtract','decimal_place5'],'Integers include positive whole numbers, zero and negative whole numbers. On a number line, adding a positive integer moves right and subtracting one moves left.','Explain addition across zero.','What is −3 + 5?',['Start at negative three.','Move five one-unit steps right.','The endpoint is positive two.'],'2','Walk along a floor number line spanning negative and positive positions.','Track temperature rising five degrees from −3°C.','Treating every negative sign as a request to subtract absolute values.','Locate the starting point and describe the direction of the change.','Find how far apart −3 and 2 are.'),
r('ratio',6,'Keeping things in proportion','Proportion',['multiply','divide','fraction'],'A ratio compares quantities in a stated order. Multiplying both quantities by the same non-zero positive factor preserves a positive ratio.','Create equivalent ratios and keep their order meaningful.','A drink uses water and juice in the ratio 3:2. How much juice for 9 cups of water?',['Water increases from three to nine cups: multiply by three.','Apply the same multiplier to the juice.','2 × 3 = 6 cups.'],'6 cups','Use coloured counters for the two quantities and copy the whole group.','Scale a recipe while keeping its taste the same.','Adding the same amount to both terms and assuming the ratio stays equal.','Compare the number of complete original groups in each mixture.','Solve the same ratio when the juice quantity is given first.'),
r('prime6',6,'Prime numbers and common factors','Number sense',['factors4','divide4'],'A prime number has exactly two distinct positive factors: one and itself. One is neither prime nor composite because it has only one positive factor.','Identify prime factors and find a highest common factor.','Find the HCF of 12 and 18.',['Factors of 12 include 1, 2, 3, 4, 6, 12.','Factors of 18 include 1, 2, 3, 6, 9, 18.','The greatest common factor is six.'],'6','Make equal groups that divide both collections exactly.','Find the largest equal packet size for two different collections.','Calling one prime or confusing common factors with common multiples.','Count distinct factors and test exact divisibility.','Find the smallest common multiple of the same numbers.'),
r('fraction_calc6',6,'Fractions with different denominators','Fractions',['fraction','fraction_add5'],'Before adding different-sized fractional parts, express them using a common part size. Equivalent fractions allow this without changing either quantity.','Add simple unlike fractions with a visual or numerical explanation.','What is 1/2 + 1/3?',['Use sixths as the common-sized parts.','1/2 = 3/6 and 1/3 = 2/6.','3/6 + 2/6 = 5/6.'],'5/6','Align equal-length strips divided into halves, thirds and sixths.','Join lengths of one-half metre and one-third metre.','Adding denominators without finding a common part size.','Show why halves and thirds are not interchangeable pieces.','Explain why the sum must lie between one-half and one whole.'),
r('angle6',6,'Angles on a straight line','Geometry',['angles5'],'Adjacent angles that form a straight line have a total of 180°. Adjacency alone is insufficient: their outside arms must point in opposite directions.','Use a straight-angle relationship to find a missing angle.','Two angles form a straight line. One is 65°. Find the other.',['A straight angle is 180°.','The two angles together fill that straight angle.','180 − 65 = 115.'],'115°','Use a straight strip and a movable ray at a marked point.','Describe a turn split into two parts along a straight path.','Assuming any adjacent angles add to 180°.','Check the outside rays form a straight line before subtracting.','Draw adjacent angles that do not form a straight line.'),
r('algebra6',6,'Using a letter for a number','Algebra',['patterns5','multiply'],'A variable is a symbol for a quantity that may be unknown or may change. In 3n, the number three multiplies n; it is not a two-digit numeral.','Interpret and evaluate a simple expression.','Find 3n + 2 when n = 4.',['Replace n by four.','Multiply first: 3 × 4 = 12.','Add two to get fourteen.'],'14','Use equal bags with the same number of counters in each bag.','Three packs of pencils and two loose pencils make 3n + 2.','Reading 3n as a concatenated number or doing addition first.','Write the implied multiplication and substitute in brackets.','Evaluate the same expression for two different values of n.'),
r('mean6',6,'Sharing a total equally','Data & chance',['data5','divide'],'The arithmetic mean is the total of the values divided by the number of values. It represents a fair-share level and need not equal an observed value.','Calculate a mean and explain what it represents.','Find the mean of 4, 6 and 8.',['Add the values: 4 + 6 + 8 = 18.','There are three values.','18 ÷ 3 = 6.'],'6','Redistribute stacks of counters into equal-height stacks.','Compare the average number of books read over three days.','Dividing by the largest value instead of the number of values.','Count the data entries separately from their total.','Explain how adding one unusually large value affects the mean.'),
r('symmetry6',6,'Symmetry and transformations','Geometry',['symmetry4','angles5'],'Reflection matches a figure across a mirror line. Rotational symmetry means a turn smaller than a full turn brings the figure into the same position.','Distinguish a mirror reflection from a turn.','What is the order of rotational symmetry of a square?',['Rotate the square through quarter turns.','It matches at 90°, 180°, 270° and 360°.','There are four matching positions in one full turn.'],'4','Turn a paper square on a traced outline.','Design a tile pattern that repeats under a quarter turn.','Counting only non-zero turns and forgetting the full-turn position.','Track equal turns through exactly one full rotation.','Compare rotational symmetry of a non-square rectangle.'),
// Class 7.
r('rational7',7,'Rational numbers and signs','Number sense',['integer','fraction_calc6'],'A rational number can be written as p/q with integers p and q and q non-zero. Equivalent signed fractions name the same point on the number line.','Operate with simple signed fractions and interpret their position.','What is −1/2 + 3/4?',['Rewrite −1/2 as −2/4.','Add the quarter counts: −2 + 3 = 1.','The result is one quarter.'],'1/4','Mark quarters around zero on a number line.','Track a change from half a unit below zero upward by three quarters.','Ignoring the negative sign while changing denominator.','Keep the sign attached to the numerator during each step.','Explain why the answer lies between zero and three quarters.'),
r('equation',7,'Finding the unknown','Algebra',['algebra6','integer'],'An equation states that two expressions have equal value. Applying the same reversible operation to both sides keeps the equality true.','Solve and check a one-step equation.','Solve x + 7 = 19.',['Subtract seven from both sides.','x = 19 − 7 = 12.','Check: 12 + 7 = 19.'],'x = 12','Use a balance model with equal weights on both sides.','An unknown number of cards plus seven makes nineteen.','Changing one side of an equation without the other.','Describe the operation performed on each side explicitly.','Solve 7 + x = 19 and explain why the answer is unchanged.'),
r('percent',7,'Out of a hundred','Proportion',['ratio','fraction_calc6'],'A percentage expresses a quantity per hundred. The whole must be identified: the same percentage of different wholes can produce different amounts.','Find a simple percentage of a stated whole.','Find 25% of 80.',['25% means 25/100 = 1/4.','Find one quarter of eighty.','80 ÷ 4 = 20.'],'20','Shade a hundred grid and connect it to a scaled whole.','Find a 25% share of eighty collected items.','Using the percentage number itself as the final amount.','Name the whole and represent the fraction of that whole.','Compare 25% of 80 with 25% of 40.'),
r('triangle_angle7',7,'Angles inside a triangle','Geometry',['angle6'],'The interior angles of a Euclidean triangle sum to 180°. The total applies to the three inside angles, not an arbitrary mixture of inside and outside angles.','Use the angle sum to find a missing interior angle.','Two interior angles are 50° and 60°. Find the third.',['Add the known interior angles: 110°.','Subtract from 180°.','180 − 110 = 70.'],'70°','Cut the three corners from a paper triangle and place them on a straight line.','Design a triangular sign with specified angles.','Using 360° as the triangle’s interior-angle total.','Rebuild the straight angle with three paper corners.','Explain why a triangle cannot contain two right angles.'),
r('circle7',7,'A circle’s boundary','Measurement',['perimeter','decimal','ratio'],'A circle’s circumference is its boundary length. The diameter is twice the radius, and circumference equals π times diameter, or 2πr.','Distinguish radius from diameter in circumference calculations.','Find the circumference when radius is 7 cm, using π = 22/7.',['Double the radius: diameter = 14 cm.','Multiply π by the diameter.','(22/7) × 14 = 44.'],'44 cm','Wrap string around a circular object and compare with its diameter.','Find the trim needed around a circular mat.','Using πr when the supplied measure is a radius.','Draw and label a radius and a full diameter before substituting.','Calculate from a diameter of 14 cm instead.'),
r('exponent7',7,'Powers and their meaning','Algebra',['multiply'],'A positive whole-number exponent counts repeated equal factors. For example, 2³ means 2 × 2 × 2, not 2 × 3.','Translate between repeated multiplication and exponential notation.','What is 3³?',['Write three factors of three.','3 × 3 = 9.','9 × 3 = 27.'],'27','Build a cube with three unit cubes along each edge.','Track a quantity tripling at each of three steps from one.','Multiplying the base by the exponent.','Write every factor before calculating.','Compare 3² and 2³ and explain why they differ.'),
r('probability7',7,'Describing chance','Data & chance',['fractions3','data5'],'For a finite set of equally likely outcomes, probability is favourable outcomes divided by total outcomes. Equal likelihood must be justified by the situation.','Describe simple probabilities and recognise the equal-likelihood condition.','What is the probability of an even number on a fair six-sided die?',['The outcomes are 1, 2, 3, 4, 5, 6.','Three outcomes are even: 2, 4, 6.','Probability = 3/6 = 1/2.'],'1/2','Label six equal cards and draw one after mixing.','Predict even outcomes in repeated fair-die rolls.','Assuming a short run must contain exactly half even results.','Separate a probability from a guarantee about a small sample.','Explain why a weighted die needs additional information.'),
r('interest7',7,'Simple interest','Proportion',['percent','multiply4'],'Simple interest is calculated on the original principal for the stated time. With an annual percentage rate, the time must be expressed in years or converted consistently.','Use a simple-interest model with compatible units.','Find simple interest on ₹1,000 at 5% per year for 2 years.',['One year’s interest is 5% of 1,000 = 50.','Simple interest uses the same principal each year.','Two years give 50 × 2 = 100.'],'₹100','Represent the principal with a bar and add equal yearly interest bars.','Compare an explicitly hypothetical classroom savings calculation.','Calculating interest on the growing total when simple interest is specified.','Keep the principal fixed and write each equal yearly addition.','Distinguish interest earned from the final amount of ₹1,100.'),
// Class 8.
r('power',8,'Laws of exponents','Algebra',['exponent7'],'Multiplying powers with the same base combines their equal factors, so a^m × a^n = a^(m+n). For a non-zero base, a^0 = 1 and a^(−n) = 1/a^n.','Explain an exponent law using expanded factors.','Simplify 2³ × 2².',['Write three factors of two, then two more.','There are five factors of two in total.','2⁵ = 32.'],'32','Group equal-factor cards and combine the groups.','Combine growth factors that repeatedly double a quantity.','Multiplying exponents instead of adding them for a product of powers.','Expand both powers and count the total factors.','Contrast 2³ × 2² with (2³)².'),
r('linear',8,'Balancing two-step equations','Algebra',['equation','rational7'],'A two-step linear equation can be solved by undoing operations in reverse order while keeping both sides equal. Substitute the result into the original equation to check it.','Solve an equation involving multiplication and addition.','Solve 3x + 4 = 19.',['Subtract four from both sides: 3x = 15.','Divide both sides by three: x = 5.','Check: 3 × 5 + 4 = 19.'],'x = 5','Use three equal bags and four loose counters on a balance model.','Three identical notebooks and a ₹4 pencil cost ₹19.','Dividing only one term on a side.','Use brackets when dividing an entire side, or subtract first.','Solve an equivalent equation written as 19 = 4 + 3x.'),
r('square_root8',8,'Squares and square roots','Number sense',['exponent7','area'],'Squaring finds the area of a square from its side length. The square-root symbol denotes the non-negative root; solving x² = k can also require a negative solution.','Distinguish a principal square root from both solutions of a square equation.','What is √81?',['Find the non-negative number whose square is 81.','9 × 9 = 81.','The principal square root is nine.'],'9','Arrange eighty-one unit tiles into a square.','Find the side of a square with area 81 cm².','Saying √81 is both +9 and −9.','Contrast the symbol √81 with the equation x² = 81.','State both solutions of x² = 81.'),
r('cube8',8,'Cubes and cube roots','Number sense',['volume5','exponent7'],'Cubing multiplies three equal factors. A cube root reverses this operation; negative numbers have negative real cube roots.','Connect a cube’s side and volume.','Find the cube root of 64.',['Look for three equal factors producing 64.','4 × 4 × 4 = 64.','The cube root is four.'],'4','Build a cube using four unit cubes along each edge.','Find the side of a cubic box with volume 64 cm³.','Using a square root when three dimensions are involved.','Label length, width and height as three factors.','Explain why the cube root of −8 is −2.'),
r('identity8',8,'Expanding algebraic identities','Algebra',['algebra6','multiply4','area'],'An identity is true for every allowed value of its variables. Expanding (a + b)² gives a² + 2ab + b² because both cross-products must be included.','Explain a square-of-a-sum expansion.','Calculate (10 + 2)² using an identity.',['10² = 100 and 2² = 4.','Two cross-products give 2 × 10 × 2 = 40.','100 + 40 + 4 = 144.'],'144','Partition a square into two squares and two rectangles.','Find the area after increasing both sides of a square.','Omitting the middle term and writing a² + b².','Label the areas of all four parts of the large square.','Use the same partition to explain (a − b)².'),
r('proportion8',8,'Direct and inverse proportion','Proportion',['ratio','percent'],'In direct proportion, the ratio of corresponding positive quantities stays constant. In inverse proportion, their product stays constant under the stated model and assumptions.','Choose the appropriate proportional model.','Three identical taps fill a tank in 8 hours. How long for six taps at the same flow rate?',['Doubling the taps doubles the total flow rate.','The fixed tank volume then takes half the time.','8 ÷ 2 = 4 hours.'],'4 hours','Distribute a fixed task among different numbers of identical equal-rate units.','Compare filling one tank with identical independent taps.','Doubling both quantities in every relationship.','Identify what remains fixed: a ratio or a total product.','Explain why the model fails if the taps’ flow rates change.'),
r('volume8',8,'Volume of a cylinder','Measurement',['area','volume5','circle7'],'A right circular cylinder has equal circular cross-sections. Its volume is the area of the circular base, πr², multiplied by perpendicular height.','Use cylinder dimensions and cubic units correctly.','Find the volume for radius 7 cm and height 5 cm, using π = 22/7.',['Base area = (22/7) × 7² = 154 cm².','Multiply by height: 154 × 5.','The volume is 770 cubic centimetres.'],'770 cm³','Stack identical circular layers to model the cylinder.','Compare capacities of cylindrical containers.','Using diameter in place of radius, or omitting the squared radius.','Label the radius and compute base area as a separate step.','Predict the effect of doubling height while keeping radius fixed.'),
r('factor8',8,'Factorising expressions','Algebra',['multiply4','identity8'],'Factorisation writes an expression as a product. Taking out a common factor reverses the distributive property and must account for every original term.','Factor out a common numerical or algebraic factor.','Factorise 6x + 9.',['Both coefficients share the factor three.','6x ÷ 3 = 2x and 9 ÷ 3 = 3.','Write 3(2x + 3), then expand to check.'],'3(2x + 3)','Group algebra tiles into three identical collections.','Separate repeated equal bundles from a total cost expression.','Factoring the first term and leaving the second term unchanged inside brackets.','Expand the proposed factorisation to compare both original terms.','Factorise 6x + 12 and verify by expansion.'),
// Class 9: topic references checked against CBSE 2026–27; teaching notes remain original drafts.
r('real9',9,'Rational and irrational numbers','Number sense',['rational7','square_root8'],'A rational number can be expressed as a ratio of integers with non-zero denominator. Irrational numbers cannot; their decimal expansions neither terminate nor eventually repeat.','Classify numbers and distinguish examples from proofs.','Is √49 rational?',['The principal square root of 49 is 7.','Seven can be written as 7/1.','Therefore √49 is rational.'],'Yes','Locate exact squares and nearby non-square roots on a number line.','Compare exact lengths with decimal approximations.','Calling every square root irrational.','Evaluate perfect-square roots before classifying.','Explain why a finite calculator display cannot by itself prove irrationality.'),
r('polynomial9',9,'Terms and degree of a polynomial','Algebra',['algebra6','exponent7'],'In a polynomial in x, exponents of x are non-negative integers and coefficients are constants. After like terms are combined, the largest exponent with a non-zero coefficient is its degree.','Identify coefficients, terms and degree.','Find the degree of 4x³ + 2x − 7.',['The non-zero powers are 3, 1 and 0.','The largest is three.','The polynomial therefore has degree three.'],'3','Use labelled term cards and group like powers.','Represent a quantity with a polynomial expression and identify its terms.','Adding exponents from separate terms to find degree.','Inspect each term separately after combining like terms.','Explain why 1/x is not a polynomial in x.'),
r('slope',9,'How a line changes','Algebra',['linear','algebra6'],'In y = mx + c, m is the change in y for a one-unit increase in x and c is the value of y when x is zero. Negative slope describes a decrease.','Interpret slope and intercept from an equation and a table.','For y = 3x + 2, what is y when x = 4?',['Multiply the input by three: 3 × 4 = 12.','Add the intercept two.','y = 14.'],'14','Plot a small input-output table on squared paper.','A hypothetical fare has a fixed start charge plus a per-kilometre amount.','Confusing the intercept with the rate of change.','Compare outputs at consecutive inputs and at input zero.','Read the same slope from two points instead of an equation.'),
r('sequence9',9,'Arithmetic and geometric sequences','Algebra',['patterns5','exponent7'],'An arithmetic progression has a constant difference; a geometric progression has a constant non-zero ratio when consecutive terms permit division. Identify the pattern before using a formula.','Distinguish equal additions from equal multiplications.','Find the fifth term of 3, 6, 12, 24, …',['Each term doubles, so the common ratio is two.','The fourth term is twenty-four.','Double it to obtain forty-eight.'],'48','Build a table of positions, differences and ratios.','Compare fixed yearly additions with repeated doubling in a mathematical model.','Applying an arithmetic formula to a geometric pattern.','Check both consecutive differences and ratios before choosing a rule.','Explain how 3, 6, 9, 12 differs from the given sequence.'),
r('coordinates9',9,'Coordinates and distance','Geometry',['integer','square_root8','triangle'],'Coordinates specify ordered horizontal and vertical positions. The distance formula applies the right-triangle relationship to horizontal and vertical differences.','Use coordinates to calculate a distance.','Find the distance from (1, 2) to (4, 6).',['The horizontal difference is three and the vertical difference is four.','Distance squared = 3² + 4² = 25.','The non-negative distance is five.'],'5 units','Plot points and draw the horizontal and vertical legs between them.','Measure straight-line distances on a unit grid map.','Adding coordinate values instead of finding coordinate differences.','Draw the displacement triangle and label each difference.','Find the midpoint of the same segment and explain the averaging.'),
r('triangle',9,'A right-triangle foundation','Geometry',['square_root8','area'],'In a right-angled triangle, the square of the hypotenuse equals the sum of the squares of the other two sides. The hypotenuse is opposite the right angle.','Apply the right-triangle relationship under its required condition.','The perpendicular sides are 6 cm and 8 cm. Find the hypotenuse.',['Compute 6² + 8² = 36 + 64 = 100.','The hypotenuse is the positive square root of 100.','Its length is ten centimetres.'],'10 cm','Compare squares built on the three sides of a right triangle.','Find a diagonal when two perpendicular distances are known.','Using the relationship for a triangle without a right angle.','Check and mark the right angle before selecting the formula.','Find a shorter side when the hypotenuse and other leg are given.'),
r('angles9',9,'Reasoning with parallel lines','Geometry',['angle6','triangle_angle7'],'When a transversal crosses parallel lines, corresponding angles are equal and co-interior angles are supplementary. The parallel-line condition is essential to these conclusions.','State the geometric condition that justifies an angle relation.','Corresponding angles lie on parallel lines. One is 68°. Find the other.',['Check the two lines are specified as parallel.','Identify the corresponding angle positions.','Corresponding angles are equal, so the other angle is 68°.'],'68°','Slide a cut-out angle along parallel lines to compare matching positions.','Explain equal directions in a drawing of parallel railway tracks.','Using corresponding-angle equality without established parallel lines.','State the given condition before naming the theorem.','Find a co-interior angle when the other is 68°.'),
r('statistics9',9,'Mean, median and mode','Data & chance',['mean6','data5'],'The mean uses every value, the median is the middle of ordered data, and the mode is a most frequent value. Different measures describe different aspects of a distribution.','Choose and calculate a suitable central measure.','Find the median of 9, 2, 5, 4, 20.',['Order the values: 2, 4, 5, 9, 20.','There are five values.','The third, middle value is five.'],'5','Order labelled data cards and locate their middle.','Compare a typical daily reading time when one day is unusually long.','Taking the middle item before sorting the data.','Arrange the values in order first, then identify the middle position.','Explain how changing 20 to 200 affects mean and median differently.'),
// Class 10.
r('real10',10,'Prime factorisation and divisibility','Number sense',['prime6','real9'],'Every integer greater than one has a prime factorisation unique apart from the order of its factors. Prime exponents help identify highest common factors and least common multiples.','Use prime factors to find HCF and LCM.','Find the LCM of 12 and 18.',['12 = 2² × 3 and 18 = 2 × 3².','Use the greatest required power of each prime.','LCM = 2² × 3² = 36.'],'36','Build factor trees, then compare prime-factor collections.','Find when two repeating schedules of 12 and 18 units meet again.','Choosing the smaller prime exponents for an LCM.','Check that the proposed result is divisible by both original numbers.','Use the same factorizations to find their HCF.'),
r('quadratic',10,'Two factors, two roots','Algebra',['factor8','linear','polynomial9'],'A quadratic equation has a non-zero squared coefficient. When a product equals zero, at least one factor is zero; factorisation can therefore reveal its real roots.','Find and verify roots of a factorised quadratic.','Solve (x − 2)(x − 5) = 0.',['Set the first factor to zero: x = 2.','Set the second factor to zero: x = 5.','Each value makes the original product zero.'],'x = 2 or x = 5','Use an area model to connect expanded and factorised expressions.','Model a mathematical measurement problem, then check which roots fit the context.','Setting both factors to zero at once or discarding one root without a reason.','Treat the two zero-factor possibilities separately and substitute each.','Expand the expression and solve the equivalent equation x² − 7x + 10 = 0.'),
r('simultaneous10',10,'Two equations, one shared solution','Algebra',['linear','slope'],'A solution of a pair of equations satisfies both simultaneously. Two lines may intersect once, be parallel and distinct, or coincide, giving one, no or infinitely many solutions.','Solve a simple pair and check both equations.','Solve x + y = 9 and x − y = 3.',['Add the equations to eliminate y: 2x = 12.','Divide by two: x = 6.','Substitute into x + y = 9 to obtain y = 3.'],'x = 6, y = 3','Plot both lines or combine balanced-equation cards.','Use a sum and a difference to determine two unknown quantities.','Accepting a pair that satisfies only one equation.','Substitute both values into both original equations.','Recognise why x + y = 9 and x + y = 4 have no common solution.'),
r('ap10',10,'Arithmetic progressions','Algebra',['patterns5','sequence9'],'An arithmetic progression adds a fixed difference d. Its nth term is a + (n − 1)d because the nth position is n − 1 steps after the first term a.','Use and explain the nth-term formula.','Find the tenth term when a = 5 and d = 3.',['The tenth term is nine steps after the first.','Nine increments contribute 9 × 3 = 27.','5 + 27 = 32.'],'32','Mark the first term and count the equal gaps between positions.','Model seats increasing by three in successive rows.','Using n increments rather than n − 1.','Check the formula at n = 1 before calculating a later term.','Find the sum of the first ten terms using paired end terms.'),
r('trig10',10,'Trigonometric ratios','Geometry',['triangle','ratio','fraction_calc6'],'For an acute angle in a right triangle, sine is opposite/hypotenuse, cosine is adjacent/hypotenuse and tangent is opposite/adjacent. The chosen angle determines opposite and adjacent.','Identify the relevant sides before forming a ratio.','A right triangle has sides 3, 4 and 5. For the angle opposite side 3, find sin θ.',['The side opposite the chosen angle is three.','The hypotenuse is five.','sin θ = opposite/hypotenuse = 3/5.'],'3/5','Label one acute angle on a right-triangle cut-out and identify its sides.','Use a right-triangle model for a slope or a line of sight.','Keeping the same opposite side after switching to the other acute angle.','Relabel the sides relative to the chosen angle each time.','Find cosine of the same angle and explain why it is 4/5.'),
r('circle10',10,'Tangents to a circle','Geometry',['circle7','angles9'],'A tangent meets a circle at one point and is perpendicular to the radius at that point. Tangent segments from the same external point to the circle have equal lengths.','Use tangent conditions to justify an angle or length.','What angle does a tangent make with the radius at the point of contact?',['Identify the point where the tangent touches the circle.','Join that point to the centre to form the radius.','The tangent and this radius are perpendicular.'],'90°','Draw a circle, its contact point and the associated radius.','Interpret a straight path that just touches a circular boundary.','Assuming any line that crosses the circle is a tangent.','Count intersection points and check the contact condition.','If one of two tangent segments from the same point is 8 cm, find the other.'),
r('probability',10,'Probability with equally likely outcomes','Data & chance',['probability7','fraction_calc6'],'For equally likely outcomes, theoretical probability is the favourable count divided by the total count. Probability lies from zero to one; an event and its complement have probabilities summing to one.','Calculate and interpret a probability, including its complement.','A bag has 3 green and 2 blue identical counters. Find P(green).',['There are five equally likely counters.','Three are green.','P(green) = 3/5; P(not green) = 2/5.'],'3/5','List individual counters as equally likely outcomes.','Draw one well-mixed counter without looking.','Using the number of colours as the denominator when colour groups differ in size.','List individual equally likely outcomes before grouping them by colour.','Predict how adding two blue counters changes P(green).'),
r('statistics10',10,'Grouped data and its mean','Data & chance',['statistics9','mean6','multiply4'],'For grouped data, class midpoints represent the values in each interval when estimating a mean. Sum midpoint × frequency and divide by total frequency; the result is generally an estimate.','Compute a grouped-mean estimate and recognise its limitation.','Midpoints 5 and 15 have frequencies 2 and 4. Estimate the mean.',['Weighted total = 5 × 2 + 15 × 4 = 70.','Total frequency = 2 + 4 = 6.','Mean estimate = 70/6 = 35/3.'],'35/3, approximately 11.67','Replace each class by its midpoint on a weighted strip diagram.','Estimate an average from measurements recorded only in intervals.','Averaging midpoints without considering their frequencies.','Make each midpoint appear as many times as its frequency specifies.','Explain why individual measurements are needed to recover the exact mean.'),
];
